// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address caller, uint256 sendAmount) public {
        vm.assume(caller != address(0));
        sendAmount = bound(sendAmount, 0, 10 ether);

        vm.deal(caller, sendAmount);

        vm.prank(caller);

        bool ok;
        try c.lockInGuess{value: sendAmount}(bytes32(uint256(0x123))) {
            ok = true;
        } catch {
            ok = false;
        }

        if (sendAmount != 1 ether) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}
